106	func validatePeriodicSimulateRequest(req *periodicSimulateRequest) ([]simTask, int64, bool) {
107		if req.Horizon == nil || *req.Horizon <= 0 || *req.Horizon > maxHorizon {
108			return nil, 0, false
109		}
110		horizon := *req.Horizon
111		if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
112			return nil, 0, false
113		}
114		tasks := make([]simTask, 0, len(*req.Tasks))
115		ids := make(map[string]struct{}, len(*req.Tasks))
116		priorities := make(map[int64]struct{}, len(*req.Tasks))
117		totalJobs := 0
118		for i := range *req.Tasks {
119			in := (*req.Tasks)[i]
120			if !validTaskID(in.ID) {
121				return nil, 0, false
122			}
123			if _, dup := ids[in.ID]; dup {
124				return nil, 0, false
125			}
126			ids[in.ID] = struct{}{}
127			if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
128				return nil, 0, false
129			}
130			if _, dup := priorities[*in.Priority]; dup {
131				return nil, 0, false
132			}
133			priorities[*in.Priority] = struct{}{}
134			if in.Execution == nil || *in.Execution <= 0 || *in.Execution > maxPeriodicValue {
135				return nil, 0, false
136			}
137			if in.Period == nil || *in.Period <= 0 || *in.Period > maxPeriodicValue {
138				return nil, 0, false
139			}
140			if in.Deadline == nil || *in.Deadline <= 0 || *in.Deadline > maxPeriodicValue ||
141				*in.Deadline > *in.Period {
142				return nil, 0, false
143			}
144			if in.Offset == nil || *in.Offset < 0 || *in.Offset >= *in.Period ||
145				*in.Offset >= horizon {
146				return nil, 0, false
147			}
148			// Jobs release at offset+k*period < horizon; offset < horizon, so the
149			// count is at least 1 and the arithmetic stays well inside int64.
150			count := (horizon-*in.Offset-1)/(*in.Period) + 1
151			totalJobs += int(count)
152			if totalJobs > maxSimulateJobs {
153				return nil, 0, false
154			}
155			jobs := make([]simJob, count)
156			for k := range jobs {
157				release := *in.Offset + int64(k)*(*in.Period)
158				jobs[k] = simJob{
159					release:   release,
160					deadline:  release + *in.Deadline,
161					remaining: *in.Execution,
162				}
163			}
164			tasks = append(tasks, simTask{
165				id:        in.ID,
166				priority:  *in.Priority,
167				execution: *in.Execution,
168				period:    *in.Period,
169				deadline:  *in.Deadline,
170				offset:    *in.Offset,
171				jobs:      jobs,
172			})
173		}
174		return tasks, horizon, true
175	}
176	
177	// simulatePeriodic runs an event-driven single-core fixed-priority
178	// fully-preemptive simulation of the expanded periodic jobs over
179	// [0, horizon). Blocking, jitter and switch overheads are ignored; a job
180	// keeps executing past its absolute deadline.
181	func simulatePeriodic(tasks []simTask, horizon int64) periodicSimulateResponse {
182		totalJobs := 0
183		for i := range tasks {
184			totalJobs += len(tasks[i].jobs)
185		}
186		completed := 0
187	
188		var segments []simSegment
189		current := -1
190		var now int64
191		for now < horizon {
192			for i := range tasks {
193				t := &tasks[i]
194				for t.released < len(t.jobs) && t.jobs[t.released].release <= now {
195					t.released++
196				}
197			}
198			if current >= 0 && tasks[current].jobs[tasks[current].active].remaining == 0 {
199				current = -1
200			}
201			// Ready task with the smallest priority value; its ready job is the
202			// oldest released incomplete one. Priorities are unique, so a tie
203			// between tasks cannot occur.
204			best := -1
205			for i := range tasks {
206				if tasks[i].active < tasks[i].released &&
207					(best == -1 || tasks[i].priority < tasks[best].priority) {
208					best = i
209				}
210			}
211			switch {
212			case current == -1:
213				current = best
214			case best != -1 && tasks[best].priority < tasks[current].priority:
215				// A strictly higher priority release preempts immediately; a new
216				// job of the same or a lower priority never does.
217				current = best
218			}
219	
220			if current == -1 {
221				// Idle: jump to the next release (or the horizon).
222				next := int64(-1)
223				for i := range tasks {
224					t := &tasks[i]
225					if t.released < len(t.jobs) {
226						if r := t.jobs[t.released].release; next == -1 || r < next {
227							next = r
228						}
229					}
230				}
231				if next == -1 {
232					now = horizon
233					break
234				}
235				now = next
236				continue
237			}
238	
239			// Run until the job completes, the horizon, or the next
240			// strictly-higher-priority release, whichever comes first.
241			cur := &tasks[current]
242			job := &cur.jobs[cur.active]
243			runEnd := horizon
244			if job.remaining < runEnd-now {
245				runEnd = now + job.remaining
246			}
247			for i := range tasks {
248				if tasks[i].priority >= cur.priority {
249					continue
250				}
251				t := &tasks[i]
252				if t.released < len(t.jobs) {
253					if r := t.jobs[t.released].release; r > now && r < runEnd {
254						runEnd = r
255					}
256				}
257			}
258	
259			segments = append(segments, simSegment{task: current, job: cur.active, start: now, end: runEnd})
260			delta := runEnd - now
261			job.executed += delta
262			job.remaining -= delta
263			now = runEnd
264			if job.remaining == 0 {
265				done := now
266				job.completion = &done
267				completed++
268				cur.active++
269				current = -1
270			}
271		}
272	
273		// Merge adjacent intervals of the same job; idle time is omitted.
274		timeline := make([]periodicSimInterval, 0, len(segments))
275		for _, seg := range segments {
276			last := len(timeline) - 1
277			if last >= 0 && timeline[last].TaskID == tasks[seg.task].id &&
278				timeline[last].Job == seg.job && timeline[last].End == seg.start {
279				timeline[last].End = seg.end
280				continue
281			}
282			timeline = append(timeline, periodicSimInterval{
283				TaskID: tasks[seg.task].id,
284				Job:    seg.job,
285				Start:  seg.start,
286				End:    seg.end,
287			})
288		}
289	
290		results := make([]periodicSimTaskResult, len(tasks))
291		for i := range tasks {
292			t := &tasks[i]
293			jobs := make([]periodicSimJobResult, len(t.jobs))
294			for j := range t.jobs {
295				jb := &t.jobs[j]
296				var status string
297				switch c := jb.completion; {
298				case c != nil && *c <= jb.deadline:
299					status = "met"
300				case c != nil:
301					status = "missed"
302				case jb.deadline <= horizon:
303					status = "missed"
304				default:
305					status = "pending"
306				}
307				jobs[j] = periodicSimJobResult{
308					Job:              j,
309					Release:          jb.release,
310					AbsoluteDeadline: jb.deadline,
311					Executed:         jb.executed,
312					Remaining:        jb.remaining,
313					Completion:       jb.completion,
314					DeadlineStatus:   status,
315				}
316			}
317			results[i] = periodicSimTaskResult{ID: t.id, Jobs: jobs}
318		}
319	
320		status := "completed"
321		if completed < totalJobs {
322			status = "horizon"
323		}
324		return periodicSimulateResponse{Status: status, Timeline: timeline, Results: results}
325	}
