	for i, at := range wantAt {
		if resp.Wakeups[i].At != at {
			t.Fatalf("wakeup[%d].At = %d, want %d", i, resp.Wakeups[i].At, at)
		}
		if got := resp.Wakeups[i].Fired[0]; got.Lateness != 0 || got.ScheduledAt != at || got.Event != i {
